package com.decod.grm;

import android.content.Context;
import android.provider.Settings;
import org.json.JSONObject;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.MessageDigest;
import java.security.PublicKey;
import java.security.Signature;
import java.security.spec.X509EncodedKeySpec;
import java.util.Locale;
import java.util.UUID;
import java.util.zip.InflaterInputStream;

final class LicenseManager {
    static final byte[] DGRM_MAGIC=new byte[]{'D','G','R','M','2','1',0};
    static final String LICENSE_PUBLIC_RAW_B64URL="Md3vP9RA5P1_-KHcgr9Oc7_ZGGsRjo5UXTYnsvoCi74";
    private LicenseManager(){}
    static String installId(Context c){android.content.SharedPreferences p=c.getSharedPreferences("grm_install",Context.MODE_PRIVATE);String x=p.getString("installId","");if(x.isEmpty()){x=UUID.randomUUID().toString().replace("-","");p.edit().putString("installId",x).apply();}return x;}
    static String rawDeviceIdentity(Context c){String androidId=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ANDROID_ID);if(androidId==null)androidId="unknown";return "android|"+androidId;}
    static String deviceFingerprint(Context c){try{byte[]h=MessageDigest.getInstance("SHA-256").digest(("G-Rm-v21|"+rawDeviceIdentity(c)).getBytes(StandardCharsets.UTF_8));return hex(java.util.Arrays.copyOfRange(h,0,12));}catch(Exception e){throw new IllegalStateException(e);}}
    static String installationCode(Context c){try{String seed=installId(c),fp=deviceFingerprint(c);byte[]h=MessageDigest.getInstance("SHA-256").digest(("G-Rm-v21-Install|"+fp+"|"+seed).getBytes(StandardCharsets.UTF_8));String x=hex(java.util.Arrays.copyOfRange(h,0,10));return String.format(Locale.ROOT,"GRM21-%s-%s-%s-%s",x.substring(0,5),x.substring(5,10),x.substring(10,15),x.substring(15,20));}catch(Exception e){throw new IllegalStateException(e);}}
    private static String hex(byte[]b){StringBuilder sb=new StringBuilder(b.length*2);for(byte v:b)sb.append(String.format(Locale.ROOT,"%02X",v));return sb.toString();}
    static JSONObject parseAndVerify(Context c,byte[]blob)throws Exception{byte[]magic=DGRM_MAGIC;if(blob.length<magic.length+4+64)throw new IllegalArgumentException(".dgrm lisans dosyası eksik");for(int i=0;i<magic.length;i++)if(blob[i]!=magic[i])throw new IllegalArgumentException(".dgrm lisans dosyası biçimi geçersiz");int n=ByteBuffer.wrap(blob,magic.length,4).order(ByteOrder.BIG_ENDIAN).getInt();int start=magic.length+4;if(n<=0||start+n+64!=blob.length)throw new IllegalArgumentException(".dgrm lisans dosyası bozuk");byte[]packed=java.util.Arrays.copyOfRange(blob,start,start+n),sig=java.util.Arrays.copyOfRange(blob,start+n,blob.length);PublicKey pub=rawEd25519PublicKey(CryptoBox.b64uDec(LICENSE_PUBLIC_RAW_B64URL));Signature verifier=Signature.getInstance("Ed25519");verifier.initVerify(pub);verifier.update(packed);if(!verifier.verify(sig))throw new IllegalArgumentException("Lisans dijital imzası geçersiz");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InflaterInputStream zin=new InflaterInputStream(new ByteArrayInputStream(packed))){byte[]buf=new byte[4096];int r,total=0;while((r=zin.read(buf))>0){total+=r;if(total>65536)throw new IllegalArgumentException("Lisans içeriği çok büyük");out.write(buf,0,r);}}JSONObject lic=new JSONObject(out.toString(StandardCharsets.UTF_8));if(lic.optInt("format")!=21)throw new IllegalArgumentException("Lisans biçimi desteklenmiyor");for(String k:new String[]{"licenseId","tenantId","installationCode","companyName","userName","licenseRole","workspaceKey"})if(lic.optString(k,"").trim().isEmpty())throw new IllegalArgumentException("Lisans içeriği eksik: "+k);if(!lic.optString("installationCode").equalsIgnoreCase(installationCode(c)))throw new IllegalArgumentException("Bu lisans bu telefon kurulumu için oluşturulmamış");if(CryptoBox.b64uDec(lic.getString("workspaceKey")).length!=32)throw new IllegalArgumentException("Lisans çalışma anahtarı geçersiz");return lic;}
    private static PublicKey rawEd25519PublicKey(byte[]raw)throws Exception{if(raw.length!=32)throw new IllegalArgumentException("Public key geçersiz");byte[]prefix=new byte[]{0x30,0x2a,0x30,0x05,0x06,0x03,0x2b,0x65,0x70,0x03,0x21,0x00};byte[]x509=new byte[prefix.length+raw.length];System.arraycopy(prefix,0,x509,0,prefix.length);System.arraycopy(raw,0,x509,prefix.length,raw.length);return KeyFactory.getInstance("Ed25519").generatePublic(new X509EncodedKeySpec(x509));}
    static String profileId(String licenseId)throws Exception{byte[]h=MessageDigest.getInstance("SHA-256").digest(("G-Rm-v21-Profile|"+licenseId.trim().toUpperCase(Locale.ROOT)).getBytes(StandardCharsets.UTF_8));StringBuilder sb=new StringBuilder("usr_");for(int i=0;i<10;i++)sb.append(String.format(Locale.ROOT,"%02x",h[i]));return sb.toString();}
    static String normalizeRole(String role){String x=role==null?"":role.trim().toLowerCase(new Locale("tr","TR"));x=x.replace('ı','i').replace('ş','s').replace('ğ','g').replace('ü','u').replace('ö','o').replace('ç','c').replace(' ','_').replace('-','_');if(x.equals("yetkili")||x.equals("admin")||x.equals("authorized"))return"yetkili";if(x.equals("yari_yonetici")||x.equals("yariyonetici")||x.equals("semi_admin")||x.equals("manager"))return"yari_yonetici";if(x.equals("kullanici")||x.equals("user")||x.equals("staff"))return"kullanici";return"";}
    static String appRole(String licenseRole){return switch(normalizeRole(licenseRole)){case"yetkili"->"admin";case"yari_yonetici"->"manager";default->"sales";};}
    static JSONObject defaultPermissions(String role)throws Exception{JSONObject p=new JSONObject();String[]all={"report.view","customer.view","customer.edit","customer.delete","customer.export","product.view","product.edit","product.delete","product.export","product.cost","visit.view","visit.edit","visit.delete","visit.all","quote.view","quote.edit","quote.delete","quote.all","template.manage","user.manage","settings.manage","backup.restore","sync.manage"};if("admin".equals(role))for(String k:all)p.put(k,true);else if("manager".equals(role)){for(String k:all)p.put(k,true);p.put("user.manage",false);}else if("sales".equals(role))for(String k:new String[]{"report.view","customer.view","customer.edit","product.view","visit.view","visit.edit","quote.view","quote.edit"})p.put(k,true);else for(String k:new String[]{"customer.view","visit.view","quote.view"})p.put(k,true);return p;}
    static boolean licenseAllows(String licenseRole,String key){String r=normalizeRole(licenseRole);if("yetkili".equals(r))return true;if("yari_yonetici".equals(r)){java.util.Set<String>s=new java.util.HashSet<>(java.util.Arrays.asList("report.view","customer.view","customer.edit","customer.delete","customer.export","product.view","product.edit","product.delete","product.export","product.cost","visit.view","visit.edit","visit.delete","visit.all","quote.view","quote.edit","quote.delete","quote.all","template.manage","backup.restore"));return s.contains(key);}if("kullanici".equals(r)){java.util.Set<String>s=new java.util.HashSet<>(java.util.Arrays.asList("report.view","customer.view","customer.edit","customer.export","product.view","visit.view","visit.edit","quote.view","quote.edit"));return s.contains(key);}return false;}
    static String profileProof(String workspaceKey,String id,String licenseId,String licenseRole)throws Exception{String msg=id.trim().toUpperCase(Locale.ROOT)+"|"+licenseId.trim().toUpperCase(Locale.ROOT)+"|"+normalizeRole(licenseRole);return CryptoBox.b64u(CryptoBox.hmacSha256(CryptoBox.tenantKey(workspaceKey),msg.getBytes(StandardCharsets.UTF_8)));}
}